import sys; sys.path.insert(0,'.')
from cvlib import folds
d=np.load('base_reads.npz'); y=d['y']; R=np.load('reserved.npy')
keep=np.setdiff1d(np.arange(768),R)
M={j:d[f'mean_hidden_L{j}'][:,keep] for j in range(13)}
def z(X): return (X-X.mean(0))/(X.std(0)+1e-6)
def pcv(F, y, lams, seeds=(0,1,2)):
    # primal ridge, features already scaled
    Y=np.eye(8)[y]; out={}
    for lam in lams:
        a=[]
        for s in seeds:
            f=folds(y,5,s); S=np.zeros((len(y),8))
            for i in range(5):
                tr=f!=i; te=f==i
                mu=F[tr].mean(0); Ft=F[tr]-mu
                A=np.linalg.solve(Ft@Ft.T+lam*np.eye(tr.sum()), Y[tr]-Y[tr].mean(0))
                S[te]=(F[te]-mu)@(Ft.T@A)
            a.append((S.argmax(1)==y).mean())
        out[lam]=round(100*np.mean(a),2)
    return out
top=8
Z=z(M[top]); Zn=Z/np.linalg.norm(Z,axis=1,keepdims=True)*np.sqrt(Z.shape[1])  # norm sqrt(d)
lin26=np.hstack([z(M[2]),z(M[6])])/np.sqrt(760)
rng=np.random.RandomState(0)
